// Calcular el mes anterior
const now = new Date();
now.setMonth(now.getMonth() - 1);
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');

return [{
  json: {
    month: `${year}-${month}-01`,
    month_label: now.toLocaleDateString('es-PA', { month: 'long', year: 'numeric' })
  }
}];

const kpisRaw = $('Get Monthly KPIs').first().json.kpis;
const kpis = typeof kpisRaw === 'string' ? JSON.parse(kpisRaw) : kpisRaw;
const agents = $('Aggregate Agents').first().json.agents;
const monthLabel = $('Calculate Previous Month').first().json.month_label;

const slaGlobal = kpis.sla_global;
const slaOk = slaGlobal.achieved_pct >= 80;
const slaEmoji = slaOk ? '✅' : '❌';

// Top 3 agents
const top3 = agents.slice(0, 3).map((a, i) => 
  `${['🥇','🥈','🥉'][i]} ${a.agent_name} — ${a.in_time_pct}% IT | ${a.total_cases} casos | avg ${a.avg_aging}d`
).join('\n');

const body = [
  `📊 *Reporte Mensual BO System — ${monthLabel}*`,
  '',
  `${slaEmoji} *SLA Global: ${slaGlobal.achieved_pct}%* (meta: 80%)`,
  '',
  '*📋 RMA Cancellations*',
  `   Total: ${kpis.cancellations.total} | Completados: ${kpis.cancellations.completed} | IT: ${kpis.cancellations.in_time_pct}%`,
  '',
  '*💳 Credit Notes*',
  `   Total: ${kpis.credit_notes.total} | Monto: $${Number(kpis.credit_notes.total_amount).toLocaleString()} | IT: ${kpis.credit_notes.in_time_pct}%`,
  '',
  '*💰 Refunds*',
  `   Total: ${kpis.refunds.total} | Monto: $${Number(kpis.refunds.total_amount).toLocaleString()} | IT: ${kpis.refunds.in_time_pct}%`,
  '',
  '*🏆 Top Agentes del Mes*',
  top3,
  '',
  `_Generado automáticamente — BO System Philips_`
].join('\n');

return [{ json: { body, month_label: monthLabel, kpis, sla_ok: slaOk } }];
